-- 245: Original BrillaPrep BECE gap beta questions, subj_bece_science, part 1.
-- Curriculum-blueprint-aligned practice; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _expected_245 (question_id TEXT PRIMARY KEY, topic_id TEXT NOT NULL, subject_id TEXT NOT NULL, exam_type_id TEXT NOT NULL, question_text TEXT NOT NULL, question_type TEXT NOT NULL, options TEXT NOT NULL, correct_answer TEXT NOT NULL, explanation TEXT NOT NULL, difficulty TEXT NOT NULL, points INTEGER NOT NULL, marks INTEGER NOT NULL, time_limit INTEGER NOT NULL, command_word TEXT NOT NULL, assessment_objective TEXT NOT NULL);
DELETE FROM _expected_245;
INSERT INTO _expected_245(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_science_agric_b001_001','topic_bece_science_agric','subj_bece_science','exam_bece','Which soil type usually holds the most water?','multiple_choice','["A. Sandy soil","B. Gravel","C. Coarse stones","D. Clay soil"]','D','Clay has very small particles and pore spaces, so water drains more slowly and is retained more strongly than in sandy soil. Therefore the correct answer is D: Clay soil.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_science_agric_b001_002','topic_bece_science_agric','subj_bece_science','exam_bece','Why is loam often suitable for crop growth?','multiple_choice','["A. It balances drainage, water retention, air and nutrients","B. It contains no mineral particles","C. It prevents every pest","D. It never needs organic matter"]','A','Loam combines sand, silt, clay and organic matter in proportions that support roots, drainage, aeration and nutrient supply. Therefore the correct answer is A: It balances drainage, water retention, air and nutrients.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_003','topic_bece_science_agric','subj_bece_science','exam_bece','What does soil pH measure?','multiple_choice','["A. The number of earthworms","B. The soil’s total mass","C. How acidic or alkaline the soil is","D. The height of crops"]','C','Soil pH expresses acidity or alkalinity and affects nutrient availability and the activity of many soil organisms. Therefore the correct answer is C: How acidic or alkaline the soil is.','easy',1,1,90,'Define','AO1'),
  ('q_bece_science_agric_b001_004','topic_bece_science_agric','subj_bece_science','exam_bece','How does humus improve soil?','multiple_choice','["A. It seals all pore spaces","B. It removes all organisms","C. It turns soil into rock","D. It adds nutrients and improves structure and water holding"]','D','Humus from decomposed material contributes nutrients, binds particles into stable aggregates and helps soil retain useful moisture. Therefore the correct answer is D: It adds nutrients and improves structure and water holding.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_005','topic_bece_science_agric','subj_bece_science','exam_bece','Which practice reduces erosion on a sloping farm?','multiple_choice','["A. Making channels straight downhill","B. Leaving soil bare","C. Planting along contour lines","D. Burning all residues"]','C','Contour farming slows runoff across the slope, allowing more infiltration and reducing the water’s ability to carry soil away. Therefore the correct answer is C: Planting along contour lines.','medium',1,1,90,'Apply','AO2'),
  ('q_bece_science_agric_b001_006','topic_bece_science_agric','subj_bece_science','exam_bece','Why is mulch placed around crops?','multiple_choice','["A. To stop roots receiving air","B. To reduce evaporation, suppress weeds and protect soil","C. To increase runoff speed","D. To attract every crop pest"]','B','Mulch covers the surface, conserving moisture, reducing weed emergence and cushioning soil against raindrop impact. Therefore the correct answer is B: To reduce evaporation, suppress weeds and protect soil.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_007','topic_bece_science_agric','subj_bece_science','exam_bece','Two plots grew maize last season. One is planted with cowpea before maize returns; the other repeats maize. What benefit is expected in the first plot?','multiple_choice','["A. The cowpea phase can improve nitrogen supply and interrupt maize-specific pests","B. Cowpea removes every soil nutrient before maize","C. Repeating maize always eliminates crop diseases","D. The rotation makes rainfall unnecessary"]','A','Cowpea is a legume associated with nitrogen-fixing bacteria, and changing the host crop can interrupt pests and diseases that build up under continuous maize. Therefore the correct answer is A: The cowpea phase can improve nitrogen supply and interrupt maize-specific pests.','hard',1,1,90,'Explain','AO3'),
  ('q_bece_science_agric_b001_008','topic_bece_science_agric','subj_bece_science','exam_bece','Which seed is best for planting?','multiple_choice','["A. A healthy mature seed of a suitable variety","B. A mouldy damaged seed","C. An immature shrivelled seed","D. A seed from an unknown diseased plant"]','A','Healthy mature seed with known varietal qualities has a better chance of germinating uniformly and establishing vigorous plants. Therefore the correct answer is A: A healthy mature seed of a suitable variety.','medium',1,1,90,'Select','AO2'),
  ('q_bece_science_agric_b001_009','topic_bece_science_agric','subj_bece_science','exam_bece','What three conditions are generally needed for seed germination?','multiple_choice','["A. Salt, smoke and darkness only","B. Fertiliser, pesticide and wind","C. Water, oxygen and suitable temperature","D. Clay, stones and bright paint"]','C','Water activates metabolism, oxygen supports respiration and a suitable temperature allows enzymes to function during germination. Therefore the correct answer is C: Water, oxygen and suitable temperature.','medium',1,1,90,'Identify','AO2'),
  ('q_bece_science_agric_b001_010','topic_bece_science_agric','subj_bece_science','exam_bece','Why is correct crop spacing important?','multiple_choice','["A. It guarantees every seed survives","B. It removes all labour","C. It makes soil nutrients unlimited","D. It limits competition while allowing useful field coverage"]','D','Appropriate spacing balances access to light, water and nutrients with plant population, air movement and management access. Therefore the correct answer is D: It limits competition while allowing useful field coverage.','medium',1,1,90,'Explain','AO2');
CREATE TABLE IF NOT EXISTS _migration_245_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_245_guard;
INSERT INTO _migration_245_guard(valid) SELECT CASE WHEN
  (SELECT COUNT(*) FROM _expected_245) = 10
  AND NOT EXISTS (SELECT 1 FROM _expected_245 e LEFT JOIN topics t ON t.id=e.topic_id LEFT JOIN subjects s ON s.id=t.subject_id WHERE t.id IS NULL OR t.subject_id IS NOT e.subject_id OR s.exam_type_id IS NOT e.exam_type_id)
  AND NOT EXISTS (SELECT 1 FROM questions q JOIN _expected_245 e ON e.question_id=q.id WHERE NOT (q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective))
  AND NOT EXISTS (SELECT 1 FROM question_content_releases r JOIN _expected_245 e ON e.question_id=r.question_id WHERE NOT (r.batch_id IS 'bece-science-agric-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1))
  AND NOT EXISTS (SELECT 1 FROM question_bank_remediation_log l JOIN _expected_245 e ON e.question_id=l.entity_id WHERE l.migration_id='245_bece_science_agric_beta_part_1' AND NOT (l.migration_id IS '245_bece_science_agric_beta_part_1' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-science-agric-beta-001'))
  AND (((SELECT COUNT(*) FROM questions q JOIN _expected_245 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_245 e ON e.question_id=r.question_id)=0 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_245 e ON e.question_id=l.entity_id WHERE l.migration_id='245_bece_science_agric_beta_part_1') IN (0,10))
    OR ((SELECT COUNT(*) FROM questions q JOIN _expected_245 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_245 e ON e.question_id=r.question_id WHERE r.batch_id IS 'bece-science-agric-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)=10 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_245 e ON e.question_id=l.entity_id WHERE l.migration_id IS '245_bece_science_agric_beta_part_1' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-science-agric-beta-001')=10))
THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) SELECT question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective FROM _expected_245;
INSERT OR IGNORE INTO question_content_releases (question_id,batch_id,quality_assurance,release_channel,content_label,source_url,official_exam_board_content,feedback_enabled) SELECT q.id,'bece-science-agric-beta-001','automated_beta','beta','Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.','https://nacca.gov.gh/common-core-programme-ccp/',0,1 FROM questions q JOIN _expected_245 e ON e.question_id=q.id;
INSERT OR IGNORE INTO question_bank_remediation_log (migration_id,entity_type,entity_id,field_name,old_value,new_value) SELECT '245_bece_science_agric_beta_part_1','question',q.id,'insert',NULL,'bece-science-agric-beta-001' FROM questions q JOIN _expected_245 e ON e.question_id=q.id;
INSERT INTO _migration_245_guard(valid) SELECT CASE WHEN
  (SELECT COUNT(*) FROM questions q JOIN _expected_245 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10
  AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_245 e ON e.question_id=r.question_id WHERE r.batch_id IS 'bece-science-agric-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)=10
  AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_245 e ON e.question_id=l.entity_id WHERE l.migration_id IS '245_bece_science_agric_beta_part_1' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-science-agric-beta-001')=10
  AND NOT EXISTS (SELECT 1 FROM questions q JOIN _expected_245 e ON e.question_id=q.id JOIN questions other ON other.id IS NOT q.id AND lower(trim(other.question_text))=lower(trim(q.question_text)))
THEN 1 ELSE 0 END;
DROP TABLE _expected_245;
DROP TABLE _migration_245_guard;
